initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response containing:
        Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/ResourceNotFound' and
        Response body containing 'title' element and
        Response Status Code set to 404
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions/{subscription_id}'
        method set to 'PATCH'
        Update Context Source Registration Subscription with subscription id set to 'urn:ngsi-ld:Subscription:unknowSubscription' and subscription update fragment set to '${subscription_update_fragment}'
}
